const clusters={
'Product Innovation':{college:'College of Engineering',description:'Explore product design, evaluate feasibility, and develop ideas toward commercialization.',adviser:'Ted Graef',email:'jtg150@psu.edu'},
'New Ventures':{college:'Smeal College of Business',description:'Build the management skills to create and grow a company, balance resources, and develop a team.',adviser:'Sean Doherty',email:'spd5897@psu.edu'},
'Social Entrepreneurship':{college:'College of Engineering',description:'Develop sustainable ventures with communities, using design and technology to address social challenges. Field experience is part of this pathway.',adviser:'John Gershenson',email:'jzg322@psu.edu'},
'Arts Entrepreneurship':{college:'College of Arts and Architecture',description:'Connect creative work with entrepreneurial skills and explore how to build opportunities in the arts.',adviser:'Jonathan Gangi',email:'jjg27@psu.edu'},
'Bio-Tech':{college:'Eberly College of Science',description:'Connect a foundation in biology with the development of biotechnology ideas and ventures.',adviser:'Beatrice Sirakaya',email:'bxs205@psu.edu'},
'Digital Entrepreneurship and Innovation':{college:'College of Information Sciences and Technology',description:'Explore entrepreneurial opportunities at the intersection of digital technology, organizations, and innovation.',adviser:'Betsy Campbell',email:'bjc28@psu.edu'},
'Entrepreneurship as Advocacy':{college:'College of the Liberal Arts',description:'Use entrepreneurial approaches to improve public life and create organizations that advance positive change.',adviser:'Chris Spielvogel',email:'jcs111@psu.edu'},
'Food and Bio-innovation':{college:'College of Agricultural Sciences',description:'Explore opportunities in agriculture, food, and the use of biological materials and natural resources.',adviser:'Mark Gagnon',email:'mag199@psu.edu'},
'Hospitality Management':{college:'College of Health and Human Development',description:'Develop new concepts in lodging, food service, travel, and other hospitality businesses.',adviser:'William Kidd',email:'wrk2@psu.edu'},
'New Media':{college:'Donald P. Bellisario College of Communications',description:'Explore how to create and distribute news, entertainment, and information as media technologies evolve.',adviser:'David Norloff',email:'dcn101@psu.edu'}
};
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#primary-nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='false';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(menu?.getAttribute('aria-expanded')==='true')menu.click();}));
const select=document.querySelector('#cluster-select');function updateCluster(){const c=clusters[select.value];document.querySelector('#cluster-college').textContent=c.college.toUpperCase();document.querySelector('#cluster-title').textContent=select.value;document.querySelector('#cluster-description').textContent=c.description;document.querySelector('#cluster-adviser').textContent=c.adviser;const email=document.querySelector('#cluster-email');email.textContent=c.email;email.href='mailto:'+c.email;}if(select){const initial=new URLSearchParams(location.search).get('cluster');if(initial&&clusters[initial])select.value=initial;select.addEventListener('change',updateCluster);updateCluster();}
const observer=new IntersectionObserver(items=>items.forEach(i=>{if(i.isIntersecting){i.target.classList.add('in-view');observer.unobserve(i.target);}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.querySelectorAll('.profile-photo img').forEach(img=>img.addEventListener('error',()=>img.parentElement.classList.add('image-failed')));
const form=document.querySelector('#contact-form');if(form){const msg=form.elements.message,count=document.querySelector('#character-count'),topic=form.elements.topic,status=document.querySelector('#form-status'),panel=document.querySelector('#email-preview');const requested=new URLSearchParams(location.search).get('topic');if([...topic.options].some(o=>o.value===requested))topic.value=requested;msg.addEventListener('input',()=>count.textContent=msg.value.length);let delivery=false,body='',recipient='';
fetch('/api/contact',{headers:{Accept:'application/json'}}).then(r=>r.ok?r.json():null).then(data=>{delivery=data?.configured===true;if(delivery){document.querySelector('#submit-contact').firstChild.textContent='Send your message';document.querySelector('#form-note').textContent='Your message will be sent to the E-SHIP program contact. We use your details to respond to this inquiry.';}}).catch(()=>{});
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(data.website)return;recipient=data.topic==='Courses & enrollment'?'btg125@psu.edu':'jtg150@psu.edu';body='Hello '+(recipient==='btg125@psu.edu'?'Brad':'Ted')+',\n\n'+data.message+'\n\nName: '+data.name+'\nEmail: '+data.email+'\n'+(data.major?'Major / organization: '+data.major+'\n':'')+'Topic: '+data.topic;const submit=document.querySelector('#submit-contact');if(delivery){submit.disabled=true;status.textContent='Sending your message…';try{const r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Please try again.');status.textContent='Your message was sent. Thank you for reaching out.';form.reset();count.textContent='0';return;}catch{status.textContent='We couldn’t send your message. You can review it and send it from your email app below.';}finally{submit.disabled=false;}}
const mail=document.querySelector('#preview-recipient');mail.textContent=recipient;mail.href='mailto:'+recipient;document.querySelector('#preview-text').textContent=body;document.querySelector('#open-email').href='mailto:'+recipient+'?subject='+encodeURIComponent('E-SHIP inquiry: '+data.topic)+'&body='+encodeURIComponent(body);form.hidden=true;panel.hidden=false;panel.setAttribute('tabindex','-1');panel.focus();});document.querySelector('#edit-message').addEventListener('click',()=>{panel.hidden=true;form.hidden=false;msg.focus();});document.querySelector('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('To: '+recipient+'\nSubject: E-SHIP inquiry: '+topic.value+'\n\n'+body);document.querySelector('#copy-status').textContent='Copied. Paste into your email app to send.';}catch{document.querySelector('#copy-status').textContent='Select and copy the message above, then paste it into your email app.';}});}
